// ABOUTME: Guards the LLM-visibility contract for generated cookbook hub pages:
// ABOUTME: author pages are excluded from agent surfaces, topic pages are kept.

import { describe, expect, test } from 'bun:test';
import { Glob } from 'bun';
import matter from 'gray-matter';

async function frontmatter(file: string): Promise<Record<string, unknown>> {
  return matter(await Bun.file(file).text()).data;
}

const authors = [
  ...new Glob('*.mdx').scanSync({ cwd: 'content/docs/cookbook/authors', absolute: true }),
];
const topics = [
  ...new Glob('*.mdx').scanSync({ cwd: 'content/docs/cookbook/topics', absolute: true }),
];

describe('cookbook hub LLM visibility', () => {
  test('every author page is excluded from LLM surfaces', async () => {
    expect(authors.length).toBeGreaterThan(0);
    for (const file of authors) {
      expect((await frontmatter(file)).llm).toBe(false);
    }
  });

  test('topic pages remain visible to LLMs', async () => {
    expect(topics.length).toBeGreaterThan(0);
    for (const file of topics) {
      expect((await frontmatter(file)).llm).not.toBe(false);
    }
  });
});

// ABOUTME: Tests for getLLMText, which renders a page as LLM-facing markdown
// ABOUTME: with an absolute URL and an optional llms.txt index pointer.
import { describe, expect, test } from 'bun:test';
import { getLLMText, LLMS_INDEX_POINTER, shouldIncludeLLMPage } from '../lib/get-llm-text';

// Minimal stand-in for a fumadocs page; typed any since building a real
// InferPageType requires the full fumadocs loader.
function fakePage(overrides: Record<string, unknown> = {}): any {
  return {
    url: '/overview/steel-cli',
    data: {
      title: 'Steel CLI',
      content: 'Run browser automation from the terminal.',
      ...overrides,
    },
  };
}

describe('shouldIncludeLLMPage', () => {
  test('includes pages by default', () => {
    expect(shouldIncludeLLMPage(fakePage())).toBe(true);
  });

  test('excludes pages with llm: false in page data', () => {
    expect(shouldIncludeLLMPage(fakePage({ llm: false }))).toBe(false);
  });

  test('excludes pages with llm: false in raw frontmatter', () => {
    const content = ['---', 'title: Hidden', 'llm: false', '---', '', 'Body.'].join('\n');
    expect(shouldIncludeLLMPage(fakePage({ content }))).toBe(false);
  });

  test('keeps pages whose frontmatter sets llm: true', () => {
    const content = ['---', 'title: Visible', 'llm: true', '---', '', 'Body.'].join('\n');
    expect(shouldIncludeLLMPage(fakePage({ content }))).toBe(true);
  });
});

describe('getLLMText', () => {
  test('renders the title and an absolute URL', async () => {
    const text = await getLLMText(fakePage());
    expect(text).toStartWith('# Steel CLI\n');
    expect(text).toContain('URL: https://docs.steel.dev/overview/steel-cli');
  });

  test('omits the index pointer by default', async () => {
    const text = await getLLMText(fakePage());
    expect(text).not.toContain('Full docs index');
  });

  test('prepends the index pointer exactly once when requested', async () => {
    const text = await getLLMText(fakePage(), { indexPointer: true });
    expect(text).toStartWith(`${LLMS_INDEX_POINTER}\n\n# Steel CLI\n`);
    expect(text.split('Full docs index').length).toBe(2);
  });

  test('the pointer is a blockquote linking to llms.txt', () => {
    expect(LLMS_INDEX_POINTER).toBe('> Full docs index: https://docs.steel.dev/llms.txt');
  });

  test('strips frontmatter and MDX artifacts from page content', async () => {
    const content = [
      '---',
      'title: Quickstart',
      'description: Get going.',
      '---',
      '',
      '<RecipeJsonLd slug="quickstart" />',
      '',
      ':::callout',
      'type: tip',
      'Mind the gap.',
      ':::',
      '',
      '```typescript Typescript -wcn -f main.ts',
      "import Steel from 'steel-sdk';",
      'const s = new Steel();',
      '```',
      '',
      '<Tabs items={["TypeScript"]} groupId="lang">',
      '<Tab id="typescript" className="cookbook-concept-tab">',
      'Drive the browser.',
      '</Tab>',
      '</Tabs>',
    ].join('\n');
    const text = await getLLMText(fakePage({ content }), { indexPointer: true });
    const body = text.split('\n\n').slice(1).join('\n\n');

    expect(body).not.toContain('title: Quickstart');
    expect(body).not.toContain('RecipeJsonLd');
    expect(body).not.toContain(':::');
    expect(body).not.toContain('type: tip');
    expect(body).not.toContain('<Tab');
    expect(body).toContain('Mind the gap.');
    expect(body).toContain('```typescript\nimport Steel');
    expect(body).toContain('const s = new Steel();');
    expect(body).not.toContain('-wcn');
    expect(body).toContain('**TypeScript**');
    expect(body).toContain('Drive the browser.');
  });
});

// ABOUTME: Tests the public markdown share URL built for the LLM share UI:
// ABOUTME: page path + .md suffix, with the docs root pointing at /llms.txt.
import { describe, expect, test } from 'bun:test';
import { getPublicMarkdownUrl } from '../hooks/use-llms-txt';

const ORIGIN = 'https://docs.steel.dev';

describe('getPublicMarkdownUrl', () => {
  test('appends .md to the page path', () => {
    expect(getPublicMarkdownUrl('/overview/sessions-api/quickstart', ORIGIN)).toBe(
      'https://docs.steel.dev/overview/sessions-api/quickstart.md',
    );
  });

  test('never exposes the internal /llms.mdx rewrite target', () => {
    expect(getPublicMarkdownUrl('/overview/intro', ORIGIN)).not.toContain('/llms.mdx');
  });

  test('strips a legacy /docs prefix before appending .md', () => {
    expect(getPublicMarkdownUrl('/docs/overview/intro', ORIGIN)).toBe(
      'https://docs.steel.dev/overview/intro.md',
    );
  });

  test('points the docs root at the llms.txt index', () => {
    expect(getPublicMarkdownUrl('/', ORIGIN)).toBe('https://docs.steel.dev/llms.txt');
  });

  test('returns an empty string without a pathname', () => {
    expect(getPublicMarkdownUrl(null, ORIGIN)).toBe('');
  });
});

// ABOUTME: Tests for the RFC 9727 API catalog served at /.well-known/api-catalog,
// ABOUTME: covering the linkset shape and that markdown negotiation leaves it alone.
import { describe, expect, test } from 'bun:test';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import { isNegotiableDocsPath } from '../lib/markdown-negotiation';

const CATALOG_PATH = '/.well-known/api-catalog';

type Link = { href: string; type?: string };
type LinksetEntry = {
  anchor: string;
  item?: Link[];
  'service-desc'?: Link[];
  'service-doc'?: Link[];
};

const catalog = JSON.parse(
  readFileSync(
    fileURLToPath(new URL('../public/.well-known/api-catalog', import.meta.url)),
    'utf8',
  ),
) as { linkset: LinksetEntry[] };

function entryFor(anchor: string): LinksetEntry | undefined {
  return catalog.linkset.find((entry) => entry.anchor === anchor);
}

describe('api catalog document', () => {
  test('is a linkset anchored at its own well-known URI', () => {
    expect(Array.isArray(catalog.linkset)).toBe(true);
    expect(entryFor(`https://docs.steel.dev${CATALOG_PATH}`)).toBeDefined();
  });

  test('lists the Steel API as a catalog item', () => {
    const items = entryFor(`https://docs.steel.dev${CATALOG_PATH}`)?.item ?? [];
    expect(items.map((item) => item.href)).toContain('https://api.steel.dev');
  });

  test('describes the API with the canonical OpenAPI spec, not a docs copy', () => {
    const [desc] = entryFor('https://api.steel.dev')?.['service-desc'] ?? [];

    // Pointing at the spec the API itself serves keeps one canonical copy, so
    // the catalog cannot advertise a spec that has drifted from the live API.
    expect(desc?.href).toBe('https://api.steel.dev/sdk-openapi.json');
    expect(desc?.type).toBe('application/json');
  });

  test('links human documentation for the API', () => {
    const [doc] = entryFor('https://api.steel.dev')?.['service-doc'] ?? [];
    expect(doc?.href).toStartWith('https://');
    expect(doc?.type).toBe('text/html');
  });

  test('every link is an absolute https URL', () => {
    for (const entry of catalog.linkset) {
      const links = [
        ...(entry.item ?? []),
        ...(entry['service-desc'] ?? []),
        ...(entry['service-doc'] ?? []),
      ];
      for (const link of links) {
        expect(link.href).toStartWith('https://');
      }
    }
  });
});

describe('api catalog and markdown negotiation', () => {
  test('is excluded from markdown negotiation', () => {
    // The path has no file extension, so without an explicit exclusion the
    // middleware would treat it as a docs page and rewrite it into a 404.
    expect(isNegotiableDocsPath(CATALOG_PATH)).toBe(false);
  });
});

// ABOUTME: Tests for the llm-markdown transforms that strip MDX noise (frontmatter,
// ABOUTME: CodeHike fence flags, directive fences, JSX components) from LLM-served markdown.
import { describe, expect, test } from 'bun:test';
import {
  cleanCodeFences,
  cleanMdxForLLM,
  collapseBlankLines,
  stripDirectiveFences,
  stripFrontmatter,
  stripJsxComponents,
  stripMediaElements,
  stripModuleStatements,
} from '../lib/llm-markdown';

describe('stripFrontmatter', () => {
  test('removes a leading frontmatter block', () => {
    const input = '---\ntitle: Quickstart\nsidebarTitle: Quickstart\n---\n\n### Overview\n';
    expect(stripFrontmatter(input)).toBe('### Overview\n');
  });

  test('keeps a thematic break in the document body', () => {
    const input = 'Intro.\n\n---\n\nAfter the break.';
    expect(stripFrontmatter(input)).toBe(input);
  });

  test('passes through content without frontmatter', () => {
    const input = '# Title\n\nProse.';
    expect(stripFrontmatter(input)).toBe(input);
  });
});

describe('stripModuleStatements', () => {
  test('strips top-level ESM imports but keeps prose', () => {
    const out = stripModuleStatements("import Image from 'next/image';\n\nProse.");
    expect(out).not.toContain('import Image');
    expect(out).toContain('Prose.');
  });

  test('strips named and semicolon-less import forms', () => {
    expect(stripModuleStatements("import { Foo } from 'bar'\nProse.").trim()).toBe('Prose.');
  });

  test('strips top-level ESM exports but keeps prose', () => {
    const out = stripModuleStatements('export const x = 1;\nProse.');
    expect(out).not.toContain('export const');
    expect(out).toContain('Prose.');
    expect(stripModuleStatements('export default App;\nProse.')).not.toContain('export default');
  });

  test('does not strip Python imports inside code fences', () => {
    const input = '```python\nimport os\nimport requests\n```\nProse.';
    expect(stripModuleStatements(input)).toBe(input);
  });

  test('does not strip bare Python-style imports outside fences', () => {
    // No quoted module specifier, so not an ESM import; left untouched.
    expect(stripModuleStatements('import os\nProse.')).toBe('import os\nProse.');
  });

  test('ignores the word import in prose', () => {
    expect(stripModuleStatements("We import 'style' here.\nMore.")).toBe(
      "We import 'style' here.\nMore.",
    );
  });
});

describe('stripMediaElements', () => {
  test('drops a self-contained video tag but keeps surrounding prose', () => {
    const out = stripMediaElements('Before.\n<video src="/x.mp4" controls></video>\nAfter.');
    expect(out).toContain('Before.');
    expect(out).toContain('After.');
    expect(out).not.toContain('<video');
  });

  test('drops a self-closing video tag', () => {
    expect(stripMediaElements('<video src="/x.mp4" />\nAfter.')).not.toContain('<video');
  });

  test('drops a multi-line video block', () => {
    const out = stripMediaElements('<video controls>\ncaption\n</video>\nAfter.');
    expect(out).not.toContain('<video');
    expect(out).not.toContain('caption');
    expect(out).toContain('After.');
  });

  test('ignores video tags inside code fences', () => {
    const input = '```html\n<video src="x.mp4"></video>\n```';
    expect(stripMediaElements(input)).toBe(input);
  });
});

describe('cleanCodeFences', () => {
  test('reduces a CodeHike info string to the language', () => {
    const input = '```typescript Typescript -wcn -f steel-client.ts\nconst a = 1;\n```';
    expect(cleanCodeFences(input)).toBe('```typescript\nconst a = 1;\n```');
  });

  test('handles title and flag variants', () => {
    expect(cleanCodeFences('```bash Terminal -wc\nls\n```')).toBe('```bash\nls\n```');
    expect(cleanCodeFences('```typescript !! Typescript -wcn\nx\n```')).toBe(
      '```typescript\nx\n```',
    );
    expect(cleanCodeFences('```bash .env -wcn\nKEY=1\n```')).toBe('```bash\nKEY=1\n```');
  });

  test('leaves bare language fences unchanged', () => {
    const input = '```ts\nconst a = 1;\n```\n\n```\nplain\n```';
    expect(cleanCodeFences(input)).toBe(input);
  });

  test('converts package-install fences to npm install commands', () => {
    const input = '```package-install\nsteel-sdk playwright\n```';
    expect(cleanCodeFences(input)).toBe('```bash\nnpm install steel-sdk playwright\n```');
  });

  test('does not touch fence-like lines inside a longer fence', () => {
    const input = '````md\n```typescript Typescript -wcn\ninner\n```\n````';
    expect(cleanCodeFences(input)).toBe(input);
  });

  test('preserves indentation of indented fences', () => {
    const input = '  ```bash Terminal -wc\n  ls\n  ```';
    expect(cleanCodeFences(input)).toBe('  ```bash\n  ls\n  ```');
  });
});

describe('stripDirectiveFences', () => {
  // Adapted from the stripFaqFences suite this module absorbs.
  test('removes faq fences but keeps questions and answers', () => {
    const input = '## FAQ\n\n:::faq\n### A question?\n\nAn answer.\n:::\n\nAfter.';
    expect(stripDirectiveFences(input)).toBe('## FAQ\n\n### A question?\n\nAn answer.\n\nAfter.');
  });

  test('unwraps a callout and drops its type line', () => {
    const input = ':::callout\ntype: tip\nBe careful.\n:::\n';
    expect(stripDirectiveFences(input)).toBe('Be careful.\n');
  });

  test('drops a type line separated by a blank line', () => {
    const input = ':::callout\n\ntype: warn\n\nBody.\n:::';
    const output = stripDirectiveFences(input);
    expect(output).not.toContain('type: warn');
    expect(output).toContain('Body.');
  });

  test('keeps a callout title heading', () => {
    const input = ':::callout\ntype: info\n### Heads up\nDetails.\n:::';
    expect(stripDirectiveFences(input)).toBe('### Heads up\nDetails.');
  });

  test('unwraps directives nested inside a faq block', () => {
    const input = ':::faq\n### Q?\n\n:::callout\ntype: info\nNote.\n:::\n\nMore answer.\n:::\n';
    expect(stripDirectiveFences(input)).toBe('### Q?\n\nNote.\n\nMore answer.\n');
  });

  test('handles four-colon nesting by fence length', () => {
    const input = '::::callout\ntype: warn\nOuter.\n\n:::callout\nInner.\n:::\n\nMore.\n::::';
    const output = stripDirectiveFences(input);
    expect(output).toContain('Outer.');
    expect(output).toContain('Inner.');
    expect(output).toContain('More.');
    expect(output).not.toContain(':::');
    expect(output).not.toContain('type: warn');
  });

  test('labels objectives, prerequisites, and next-steps', () => {
    expect(stripDirectiveFences(':::objectives\n- Learn X\n:::')).toBe(
      "**What you'll learn:**\n- Learn X",
    );
    expect(stripDirectiveFences(':::prerequisites\n- Know Y\n:::')).toBe(
      '**Prerequisites:**\n- Know Y',
    );
    expect(stripDirectiveFences(':::next-steps\n- [Go](/go): There\n:::')).toBe(
      '**Next steps:**\n- [Go](/go): There',
    );
  });

  test('unwraps unknown directives', () => {
    expect(stripDirectiveFences(':::mystery\nKept.\n:::')).toBe('Kept.');
  });

  test('ignores directive markers inside code fences', () => {
    const input = '```bash\n:::callout\ntype: tip\n:::\n```';
    expect(stripDirectiveFences(input)).toBe(input);
  });

  test('ignores ::: in prose and stray closers', () => {
    const prose = 'Just prose with ::: in a sentence? No.';
    expect(stripDirectiveFences(prose)).toBe(prose);
    expect(stripDirectiveFences('No open fence.\n:::\nStill here.')).toBe(
      'No open fence.\n:::\nStill here.',
    );
  });

  test('keeps the body of an unterminated directive', () => {
    expect(stripDirectiveFences(':::callout\nBody at EOF')).toBe('Body at EOF');
  });
});

